import itertools

def check_m(m):
    if m % 2 == 0:
        return False

    edges = list(itertools.combinations(range(m), 2))
    num_edges = len(edges)
    coloring = [-1] * num_edges

    def solve(edge_idx, used_subsets):
        if edge_idx == num_edges:
            return len(used_subsets) == len(list(itertools.combinations(range(m), 3)))

        u, v = edges[edge_idx]
        for color in range(m):
            # Each color must be used exactly (m-1)//2 times
            if coloring.count(color) >= (m-1)//2:
                continue

            coloring[edge_idx] = color

            # Check all triangles completed by this edge
            possible = True
            new_subsets = []
            for w in range(m):
                if w == u or w == v:
                    continue
                # Edge indices for the triangle (u, v, w)
                e1 = edge_idx
                e2 = edges.index(tuple(sorted((u, w))))
                e3 = edges.index(tuple(sorted((v, w))))

                if coloring[e2] != -1 and coloring[e3] != -1:
                    s = frozenset([coloring[e1], coloring[e2], coloring[e3]])
                    if len(s) != 3 or s in used_subsets or s in new_subsets:
                        possible = False
                        break
                    new_subsets.append(s)

            if possible:
                if solve(edge_idx + 1, used_subsets | set(new_subsets)):
                    return True

            coloring[edge_idx] = -1

        return False

    return solve(0, set())

print(f"m=3: {check_m(3)}")
print(f"m=5: {check_m(5)}")
